    def test_decode_wraparound(self):
        # 'a' was encoded from 'v' (wraparound at end of alphabet)
        self.assertEqual(decode_shift("a"), "v")
        # 'b' was encoded from 'w'
        self.assertEqual(decode_shift("b"), "w")

    def test_decode_empty_string(self):
        self.assertEqual(decode_shift(""), "")

    def test_decode_full_alphabet(self):
        self.assertEqual(decode_shift(encode_shift("abcdefghijklmnopqrstuvwxyz")), "abcdefghijklmnopqrstuvwxyz")

